using System;using System.IO;using System.Text;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Security.Cryptography;using System.Text.RegularExpressions;using System.Web.Script.Serialization;
public static class ReleaseAssets {
 static string Hash(Stream s){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 static string Hash(string p){using(var s=File.OpenRead(p))return Hash(s);}
 static string Name(string name){switch(name){case "WhiteDragon.Gaze":return "gaze.png";case "WhiteDragon.Posters":return "posters.png";case "WhiteDragon.FallbackSpec":return "fallback-spec.json";case "WhiteDragon.MotionSpec":return "motion-spec.json";case "WhiteDragon.BlinkAtlas":return "blink-atlas.png";case "WhiteDragon.BlinkSpec":return "blink-spec.json";case "WhiteDragon.FlowSpec":return "flow-spec.json";}
  var m=Regex.Match(name,@"^WhiteDragon\.(Motion|Flow)(\d{1,2})$");if(!m.Success)throw new Exception("Unrecognized resource name");return (m.Groups[1].Value=="Motion"?"motion-":"flow-")+int.Parse(m.Groups[2].Value).ToString("00")+(m.Groups[1].Value=="Motion"?".wdp":".wdf");}
 static SortedDictionary<string,string> Methods(Assembly a){var result=new SortedDictionary<string,string>();foreach(var t in a.GetTypes())foreach(var method in t.GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly).Cast<MethodBase>().Concat(t.GetConstructors(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static))){var body=method.GetMethodBody();if(body==null)continue;using(var s=new MemoryStream(body.GetILAsByteArray()))result[t.FullName+":"+method.MetadataToken]=Hash(s);}return result;}
 public static int Main(string[] args){try{
  var a=Assembly.LoadFile(Path.GetFullPath(args[1]));var report=new Dictionary<string,object>();
  if(args[0]=="extract"){
   string folder=Path.GetFullPath(args[2]);Directory.CreateDirectory(folder);var rows=new List<object>();foreach(var key in a.GetManifestResourceNames()){
    string path=Path.Combine(folder,Name(key));using(var input=a.GetManifestResourceStream(key)){
     string digest=Hash(input);input.Position=0;if(File.Exists(path)){if(Hash(path)!=digest)throw new Exception("Refusing to overwrite different existing asset: "+Path.GetFileName(path));}else using(var output=File.Create(path))input.CopyTo(output);
     rows.Add(new{resource=key,file=Name(key),sha256=digest,bytes=new FileInfo(path).Length});}}
   int motionRows;using(var stream=a.GetManifestResourceStream("WhiteDragon.MotionSpec"))using(var reader=new StreamReader(stream)){var spec=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(reader.ReadToEnd());motionRows=((System.Collections.IDictionary)spec["rows"]).Count;}if(rows.Count!=7+motionRows*2)throw new Exception("Incomplete release resources");report["ok"]=true;report["source_binary_sha256"]=Hash(args[1]);report["resources"]=rows;File.WriteAllText(Path.Combine(folder,"import-record.json"),new JavaScriptSerializer{MaxJsonLength=4000000}.Serialize(report));Console.WriteLine("Extracted and verified "+rows.Count+" resources");
  }else if(args[0]=="compare"){
   var b=Assembly.LoadFile(Path.GetFullPath(args[2]));var aa=Methods(a);var bb=Methods(b);bool methods=aa.Count==bb.Count&&aa.All(x=>bb.ContainsKey(x.Key)&&bb[x.Key]==x.Value);var names=a.GetManifestResourceNames();bool resources=names.Length==b.GetManifestResourceNames().Length;foreach(string name in names)using(var x=a.GetManifestResourceStream(name))using(var y=b.GetManifestResourceStream(name))resources&=y!=null&&Hash(x)==Hash(y);
   report["ok"]=methods&&resources;report["release_sha256"]=Hash(args[1]);report["rebuild_sha256"]=Hash(args[2]);report["identical_method_bodies"]=methods;report["method_body_count"]=aa.Count;report["identical_resources"]=resources;report["resource_count"]=names.Length;report["scope"]="Method IL and embedded assets; PE timestamps, MVID, icon and compiler provenance are outside this equality check";File.WriteAllText(args[3],new JavaScriptSerializer().Serialize(report));Console.WriteLine(new JavaScriptSerializer().Serialize(report));return methods&&resources?0:1;
  }else throw new Exception("Unknown mode");return 0;
 }catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}
}
